// merge-bot.mjs: the owner's rule, "Only if nothing visible changes". Run by merge.yml (main's copy, never a PR's).
// For one Gate run (or, on ready_for_review, the latest completed Gate run of the PR's head):
//   - the PR: open, not a draft, from a claude/* branch of this repository into main, its head the run's commit;
//   - the run green and its verdict (the gate-verdict artifact, read by merge.yml into VERDICT) gate_ok, with
//     frames_identical (and T2's, when it ran);
//   - the PR does not touch .github/workflows/merge.yml or .github/ci/merge-bot.mjs (the owner taps those);
// then squash-merge it with MERGE_TOKEN at exactly that commit. Frames changed: label needs-owner and comment the
// preview link (once a commit). No MERGE_TOKEN: says so and does nothing else.
// Env: GITHUB_TOKEN (labels, comments, reads), MERGE_TOKEN, REPO (owner/name), RUN (the Gate run's JSON),
//      VERDICT (path to verdict.json, may be missing), PR_NUMBER (ready_for_review only), DRY=1 (log, change nothing).
import fs from 'node:fs';

const REPO = process.env.REPO, API = 'https://api.github.com/repos/' + REPO, DRY = process.env.DRY === '1';
const FOOT = '\n\n---\n_Generated by [Claude Code](https://claude.ai/code)_';
const SELF = ['.github/workflows/merge.yml', '.github/ci/merge-bot.mjs'];
const say = (m) => console.log(m);
async function gh(method, p, body, token = process.env.GITHUB_TOKEN) {
  const r = await fetch(p.startsWith('http') ? p : API + p, { method, headers: { authorization: 'Bearer ' + token, accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28', 'user-agent': 'derekzhou.com-merge-bot' }, body: body ? JSON.stringify(body) : undefined });
  const t = await r.text(); let j = null; try { j = t ? JSON.parse(t) : null; } catch { j = t; }
  return { status: r.status, json: j };
}
const act = async (what, f) => { if (DRY) { say('(dry) ' + what); return { status: 0 }; } return f(); };

const run = JSON.parse(process.env.RUN || '{}');
const sha = run.head_sha, branch = run.head_branch;
say(`Gate run ${run.id} (${run.event}, ${run.conclusion}) for ${branch} @ ${sha}`);
if (!process.env.MERGE_TOKEN) { say('::notice::MERGE_TOKEN is not set, so the merge bot is idle: nothing is merged, labelled or commented. The owner adds the repository secret MERGE_TOKEN to turn it on.'); process.exit(0); }
if (!branch || !branch.startsWith('claude/')) { say(`${branch}: not a claude/* branch: left to the owner`); process.exit(0); }

let pr;
if (process.env.PR_NUMBER) pr = (await gh('GET', '/pulls/' + process.env.PR_NUMBER)).json;
else { const l = (await gh('GET', `/pulls?state=open&base=main&head=${REPO.split('/')[0]}:${encodeURIComponent(branch).replace(/%2F/g, '/')}`)).json || []; pr = l[0]; }
if (!pr || pr.state !== 'open') { say('no open PR from this branch into main'); process.exit(0); }
const n = pr.number;
if (pr.draft) { say(`#${n} is a draft: never merged by the bot`); process.exit(0); }
if (pr.base.ref !== 'main' || pr.head.repo?.full_name !== REPO) { say(`#${n}: not this repository's branch into main`); process.exit(0); }
if (pr.head.sha !== sha) { say(`#${n}'s head is ${pr.head.sha}, not the run's ${sha}: its own run decides`); process.exit(0); }

let v = null; try { v = JSON.parse(fs.readFileSync(process.env.VERDICT, 'utf8')); } catch {}
const files = [];
for (let page = 1; page < 30; page++) { const r = (await gh('GET', `/pulls/${n}/files?per_page=100&page=${page}`)).json || []; files.push(...r.map((f) => f.filename)); if (r.length < 100) break; }

async function needsOwner(why) {
  say(`#${n}: needs the owner: ${why}`);
  const marker = `<!-- merge-bot ${sha} -->`;
  const comments = (await gh('GET', `/issues/${n}/comments?per_page=100`)).json || [];
  if (comments.some((c) => (c.body || '').includes(marker))) { say('already commented for this commit'); return; }
  const checks = (await gh('GET', `/commits/${sha}/check-runs?per_page=100`)).json?.check_runs || [];
  const cf = checks.find((c) => c.name === 'Cloudflare Pages')?.output?.summary || '';
  const urls = [...cf.matchAll(/href='(https:\/\/[^']+\.pages\.dev)'/g)].map((m) => m[1]);
  const alias = 'https://' + branch.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 28).replace(/-$/, '') + '.derekzhou.pages.dev';
  const preview = urls.length ? urls.map((u) => `<${u}>`).join(' (this commit) and ') + ' (the branch)' : `<${alias}> (the branch's preview; Cloudflare's own check has not reported yet)`;
  await act('label needs-owner', async () => {
    await gh('POST', '/labels', { name: 'needs-owner', color: 'd93f0b', description: 'The merge bot left this for the owner' });
    await gh('POST', `/issues/${n}/labels`, { labels: ['needs-owner'] });
  });
  await act('comment', () => gh('POST', `/issues/${n}/comments`, { body: `${marker}\n**Left for the owner** (\`${sha.slice(0, 10)}\`): ${why}.\n\nPreview: ${preview}\n\nThe gate's run: ${run.html_url}${FOOT}` }));
}

if (files.some((f) => SELF.includes(f))) { await needsOwner('it changes the merge bot itself (' + files.filter((f) => SELF.includes(f)).join(', ') + ')'); process.exit(0); }
if (run.conclusion !== 'success' || !v || !v.gate_ok) { say(`#${n}: the gate is not green (${run.conclusion}${v ? ', gate_ok ' + v.gate_ok : ', no verdict'}): nothing to do until it is`); process.exit(0); }
if (v.sha !== sha) { say(`the verdict is for ${v.sha}, not ${sha}`); process.exit(0); }
if (!v.frames_identical) { await needsOwner(`what a visitor sees may change (${v.reason})`); process.exit(0); }
if (v.t2 && v.t2.required && !v.t2.ran) { say(`#${n}: T2 was required and did not run: left as is`); process.exit(0); }

say(`#${n}: green and frames identical (${v.reason}): merging`);
const m = await act('merge', () => gh('PUT', `/pulls/${n}/merge`, { merge_method: 'squash', sha, commit_title: `${pr.title} (#${n})` }, process.env.MERGE_TOKEN));
if (DRY || m.status === 200) { say(`merged #${n}: ${m.json?.sha || '(dry)'}`); process.exit(0); }
await needsOwner(`the merge was refused (${m.status}: ${m.json?.message || m.json}); MERGE_TOKEN needs Contents and Pull requests read/write${files.some((f) => f.startsWith('.github/workflows/')) ? ', and Workflows write for a PR that changes a workflow' : ''}`);
